// Prints the generator model as Swift. Output is a pure function of the model
// (sorted, no timestamps), so `--check` can compare bytes.
import type {
  BrandDef,
  EnumDef,
  Field,
  IR,
  StructDef,
  TypeDef,
  UnionDef,
  UntaggedDef,
  Wire,
} from "./ir.ts";
import type { HttpModel, RpcModel } from "./model.ts";
import { camel, ident, pascal, swiftString } from "./names.ts";

export const HEADER =
  "// Generated by apps/macos/scripts/generate-contracts.ts from packages/contracts. Do not edit.\n// Regenerate with: node apps/macos/scripts/generate-contracts.ts\n\nimport Foundation\n";

/** Protocol-1 files wrap their body in `extension V1 { ... }` (V1.swift declares the namespace). */
export const HEADER_V1 =
  "// Generated by apps/macos/scripts/generate-contracts.ts from apps/macos/scripts/frozen-v1 (orchestration protocol 1). Do not edit.\n// Regenerate with: node apps/macos/scripts/generate-contracts.ts\n\nimport Foundation\n";

// ---- types of wires --------------------------------------------------------------

function literalType(v: string | number | boolean): string {
  return typeof v === "string"
    ? "String"
    : typeof v === "boolean"
      ? "Bool"
      : Number.isInteger(v)
        ? "Int"
        : "Double";
}

export function baseType(ir: IR): string {
  switch (ir.k) {
    case "string":
      return "String";
    case "int":
      return "Int";
    case "double":
      return "Double";
    case "bool":
      return "Bool";
    case "json":
      return "JSONValue";
    case "void":
      return "VoidValue";
    case "never":
      return "NeverFailure";
    case "empty":
      return "EmptyObject";
    case "iso":
      return "IsoDateTime";
    case "ref":
      return ir.name;
    case "array":
      return `[${wireType(ir.elem)}]`;
    case "record":
      return `[String: ${wireType(ir.value)}]`;
    case "option":
      return `${wireType(ir.inner)}?`;
    case "literal":
      return literalType(ir.value);
  }
}
export const wireType = (w: Wire): string =>
  baseType(w.ir) + (w.nullable && w.ir.k !== "option" ? "?" : "");

/** Swift type of a stored property. */
function fieldType(f: Field): string {
  if (f.wire.ir.k === "option") return baseType(f.wire.ir);
  const t = baseType(f.wire.ir);
  if (f.tri) return `${t}??`;
  return f.optional ? `${t}?` : t;
}

// ---- default values -----------------------------------------------------------------

function defaultExpr(f: Field): string {
  const v = f.default;
  const t = baseType(f.wire.ir);
  if (v === null) return "nil";
  const ir = f.wire.ir;
  if (ir.k === "bool" && typeof v === "boolean") return String(v);
  if ((ir.k === "int" || ir.k === "double") && typeof v === "number")
    return Number.isInteger(v) ? String(v) : String(v);
  if (ir.k === "string" && typeof v === "string") return swiftString(v);
  if (ir.k === "array" && Array.isArray(v) && v.length === 0) return "[]";
  if (ir.k === "record" && v && typeof v === "object" && Object.keys(v).length === 0) return "[:]";
  return `WireDefault.value(${t}.self, json: ${swiftString(JSON.stringify(v))})`;
}

// ---- struct -----------------------------------------------------------------------------

const constExpr = (v: string | number | boolean) =>
  typeof v === "string" ? swiftString(v) : String(v);

function emitStruct(d: StructDef): string {
  const out: string[] = [];
  const conforms = ["Sendable", "Hashable", "Codable", ...(d.isError ? ["Error"] : [])].join(", ");
  out.push(`public struct ${d.name}: ${conforms} {`);
  for (const f of d.fields) out.push(`  public var ${f.id}: ${fieldType(f)}`);
  out.push("");
  // memberwise init
  const params = d.fields.map((f) => {
    const ty = fieldType(f);
    const dv = f.hasDefault ? ` = ${defaultExpr(f)}` : f.optional || f.tri ? " = nil" : "";
    return `${f.id}: ${ty}${dv}`;
  });
  out.push(`  public init(${params.join(", ")}) {`);
  for (const f of d.fields) out.push(`    self.${f.id} = ${f.id}`);
  out.push("  }");
  out.push("");
  // coding keys
  const keys: string[] = [];
  const keyLine = (id: string, key: string) => {
    const bare = id.replace(/`/g, "");
    return bare === key ? id : `${id} = ${swiftString(key)}`;
  };
  for (const c of d.consts) keys.push(keyLine(ident(c.key), c.key));
  for (const f of d.fields) keys.push(keyLine(f.id, f.key));
  out.push("  private enum CodingKeys: String, CodingKey {");
  for (const k of keys) out.push(`    case ${k}`);
  out.push("  }");
  out.push("");
  // decode
  out.push("  public init(from decoder: any Decoder) throws {");
  out.push("    let c = try decoder.container(keyedBy: CodingKeys.self)");
  if (d.fields.length === 0 && d.consts.length === 0) out.push("    _ = c");
  // Literal members must match, exactly like the TS codec; untagged unions rely on it to pick a member.
  for (const k of d.consts)
    out.push(`    try c.expectConstant(${constExpr(k.value)}, forKey: .${ident(k.key)})`);
  for (const f of d.fields) out.push(`    self.${f.id} = ${decodeExpr(f)}`);
  out.push("  }");
  out.push("");
  // encode
  out.push("  public func encode(to encoder: any Encoder) throws {");
  out.push(
    `    ${keys.length === 0 ? "_ = encoder.container(keyedBy: CodingKeys.self)" : "var c = encoder.container(keyedBy: CodingKeys.self)"}`,
  );
  for (const c of d.consts)
    out.push(`    try c.encode(${constExpr(c.value)}, forKey: .${ident(c.key)})`);
  for (const f of d.fields) {
    const s = encodeStmt(f);
    if (s) out.push(`    ${s}`);
  }
  out.push("  }");
  out.push("}");
  return out.join("\n");
}

function decodeExpr(f: Field): string {
  const ir = f.wire.ir;
  const key = `forKey: .${f.id}`;
  if (f.tri) return `try c.decodeTriState(${baseType(ir)}.self, ${key})`;
  if (ir.k === "option") {
    if (f.hasDefault) throw new Error(`Option field ${f.key} with default is not supported`);
    return `try c.decodeWireOption(${wireType(ir.inner)}.self, ${key})`;
  }
  const lossy = ir.k === "array" && ir.lossy;
  const elem = ir.k === "array" ? wireType(ir.elem) : "";
  let read: string;
  if (f.optional || f.hasDefault) {
    read = lossy
      ? `try c.decodeLossyArrayIfPresent(${elem}.self, ${key})`
      : `${f.lenient ? "try?" : "try"} c.decodeIfPresent(${baseType(ir)}.self, ${key})`;
    // A nullable field with a non-null default keeps an explicit null (the default only fills an absent key).
    if (f.hasDefault && f.default !== null && f.wire.nullable && !lossy)
      return `c.contains(.${f.id}) ? (${read}) : ${defaultExpr(f)}`;
    if (f.hasDefault && f.default !== null) return `(${read}) ?? ${defaultExpr(f)}`;
    if (f.hasDefault && !f.optional) return `(${read}) ?? ${defaultExpr(f)}`;
    return read;
  }
  return lossy
    ? `try c.decodeLossyArray(${elem}.self, ${key})`
    : `try c.decode(${baseType(ir)}.self, ${key})`;
}

function encodeStmt(f: Field): string {
  const key = `forKey: .${f.id}`;
  if (f.encode === "never") return "";
  if (f.wire.ir.k === "option") return `try c.encodeWireOption(${f.id}, ${key})`;
  if (f.encode === "omitNil")
    return f.tri
      ? `try c.encodeTriState(${f.id}, ${key})`
      : `try c.encodeIfPresent(${f.id}, ${key})`;
  return `try c.encode(${f.id}, ${key})`;
}

// ---- enum / brand ---------------------------------------------------------------------------

function emitEnum(d: EnumDef): string {
  const o: string[] = [];
  o.push(`public enum ${d.name}: Sendable, Hashable, Codable, RawRepresentable {`);
  for (const c of d.cases) o.push(`  case ${c.id}`);
  o.push("  /// A value this build does not know; kept verbatim so it round-trips.");
  o.push("  case unknown(String)");
  o.push("");
  o.push("  public init(rawValue: String) {");
  o.push("    switch rawValue {");
  for (const c of d.cases) o.push(`    case ${swiftString(c.raw)}: self = .${c.id}`);
  o.push("    default: self = .unknown(rawValue)");
  o.push("    }");
  o.push("  }");
  o.push("");
  o.push("  public var rawValue: String {");
  o.push("    switch self {");
  for (const c of d.cases) o.push(`    case .${c.id}: ${swiftString(c.raw)}`);
  o.push("    case .unknown(let value): value");
  o.push("    }");
  o.push("  }");
  o.push("");
  o.push("  public init(from decoder: any Decoder) throws {");
  o.push("    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))");
  o.push("  }");
  o.push("");
  o.push("  public func encode(to encoder: any Encoder) throws {");
  o.push("    var c = encoder.singleValueContainer()");
  o.push("    try c.encode(rawValue)");
  o.push("  }");
  o.push("}");
  return o.join("\n");
}

function emitBrand(d: BrandDef): string {
  const s = d.raw === "string";
  const t = s ? "String" : "Int";
  const lit = s ? "ExpressibleByStringLiteral" : "ExpressibleByIntegerLiteral";
  const o: string[] = [];
  o.push(
    `public struct ${d.name}: RawRepresentable, Hashable, Codable, Sendable, CustomStringConvertible, ${lit} {`,
  );
  o.push(`  public var rawValue: ${t}`);
  o.push(`  public init(rawValue: ${t}) { self.rawValue = rawValue }`);
  o.push(`  public init(_ rawValue: ${t}) { self.rawValue = rawValue }`);
  o.push(
    s
      ? "  public init(stringLiteral value: String) { rawValue = value }"
      : "  public init(integerLiteral value: Int) { rawValue = value }",
  );
  o.push("  public init(from decoder: any Decoder) throws {");
  o.push(`    rawValue = try decoder.singleValueContainer().decode(${t}.self)`);
  o.push("  }");
  o.push("  public func encode(to encoder: any Encoder) throws {");
  o.push("    var c = encoder.singleValueContainer()");
  o.push("    try c.encode(rawValue)");
  o.push("  }");
  o.push(
    s
      ? "  public var description: String { rawValue }"
      : "  public var description: String { String(rawValue) }",
  );
  o.push("}");
  return o.join("\n");
}

// ---- unions ----------------------------------------------------------------------------------------

function emitUnion(d: UnionDef): string {
  const o: string[] = [];
  const conforms = ["Sendable", "Hashable", "Codable", ...(d.isError ? ["Error"] : [])].join(", ");
  o.push(`public ${d.indirect ? "indirect " : ""}enum ${d.name}: ${conforms} {`);
  for (const v of d.variants) o.push(v.ref ? `  case ${v.id}(${v.ref})` : `  case ${v.id}`);
  if (d.fallback) o.push(`  case ${d.fallback.id}(${d.fallback.ref})`);
  o.push("  /// A variant this build does not know; kept verbatim so it round-trips.");
  o.push("  case unknown(JSONValue)");
  o.push("");
  o.push("  private enum TagKeys: String, CodingKey { case tag = " + swiftString(d.disc) + " }");
  o.push("");
  o.push("  public init(from decoder: any Decoder) throws {");
  o.push("    let c = try decoder.container(keyedBy: TagKeys.self)");
  o.push("    let tag = try? c.decodeIfPresent(String.self, forKey: .tag)");
  o.push("    switch tag {");
  const missing = d.variants.find((v) => v.missingOk);
  for (const v of d.variants) {
    const labels = v.values.map((x) => `${swiftString(x)}?`).join(", ");
    const body = v.ref ? `self = .${v.id}(try ${v.ref}(from: decoder))` : `self = .${v.id}`;
    o.push(`    case ${labels}${v === missing ? ", nil" : ""}: ${body}`);
  }
  o.push("    default:");
  if (d.fallback) {
    o.push(
      `      if let other = try? ${d.fallback.ref}(from: decoder) { self = .${d.fallback.id}(other) } else { self = .unknown(try JSONValue(from: decoder)) }`,
    );
  } else {
    o.push("      self = .unknown(try JSONValue(from: decoder))");
  }
  o.push("    }");
  o.push("  }");
  o.push("");
  o.push("  public func encode(to encoder: any Encoder) throws {");
  o.push("    switch self {");
  for (const v of d.variants) {
    if (v.ref) o.push(`    case .${v.id}(let value): try value.encode(to: encoder)`);
    else {
      o.push(`    case .${v.id}:`);
      o.push("      var c = encoder.container(keyedBy: TagKeys.self)");
      o.push(`      try c.encode(${swiftString(v.values[0]!)}, forKey: .tag)`);
    }
  }
  if (d.fallback) o.push(`    case .${d.fallback.id}(let value): try value.encode(to: encoder)`);
  o.push("    case .unknown(let value): try value.encode(to: encoder)");
  o.push("    }");
  o.push("  }");
  o.push("}");
  return o.join("\n");
}

function emitUntagged(d: UntaggedDef): string {
  const o: string[] = [];
  o.push(`public enum ${d.name}: Sendable, Hashable, Codable {`);
  for (const m of d.members) o.push(`  case ${m.id}(${wireType(m.wire)})`);
  o.push("  case unknown(JSONValue)");
  o.push("");
  o.push("  public init(from decoder: any Decoder) throws {");
  o.push("    let c = try decoder.singleValueContainer()");
  for (const m of d.members) {
    o.push(
      `    if let value = try? c.decode(${wireType(m.wire)}.self) { self = .${m.id}(value); return }`,
    );
  }
  o.push("    self = .unknown(try c.decode(JSONValue.self))");
  o.push("  }");
  o.push("");
  o.push("  public func encode(to encoder: any Encoder) throws {");
  o.push("    var c = encoder.singleValueContainer()");
  o.push("    switch self {");
  for (const m of d.members) o.push(`    case .${m.id}(let value): try c.encode(value)`);
  o.push("    case .unknown(let value): try c.encode(value)");
  o.push("    }");
  o.push("  }");
  o.push("}");
  return o.join("\n");
}

export function emitType(d: TypeDef): string {
  switch (d.kind) {
    case "struct":
      return emitStruct(d);
    case "enum":
      return emitEnum(d);
    case "brand":
      return emitBrand(d);
    case "union":
      return emitUnion(d);
    case "untagged":
      return emitUntagged(d);
  }
}

// ---- RPC / HTTP specs --------------------------------------------------------------------------------

/**
 * `XFailure` per RPC/endpoint, aliasing the shared generated union. Returns the alias
 * declarations plus the alias name chosen per key (absent when it would clash or be redundant).
 */
function failureAliases(
  items: { key: string; alias: string; failure: string | null }[],
  taken: Set<string>,
) {
  const lines: string[] = [];
  const chosen = new Map<string, string>();
  for (const { key, alias, failure } of items) {
    if (!failure || failure === alias || taken.has(alias)) continue;
    taken.add(alias);
    lines.push(`public typealias ${alias} = ${failure}`);
    chosen.set(key, alias);
  }
  return { lines, chosen };
}

export function emitRpc(rpcs: RpcModel[], taken: Set<string>): string {
  const o: string[] = [HEADER];
  const { lines, chosen } = failureAliases(
    rpcs.map((r) => ({ key: r.tag, alias: `${pascal(r.tag)}Failure`, failure: r.failure })),
    taken,
  );
  o.push(...lines, "");
  o.push("/// One `RpcSpec` per method of `WsRpcGroup` (packages/contracts/src/rpc.ts).");
  o.push("/// Tags are the literal wire tags, e.g. `subscribeServerConfig`, not a dotted guess.");
  o.push("public enum Rpc {");
  const used = new Set<string>();
  for (const r of rpcs) {
    let fn = camel(pascal(r.tag));
    for (let n = 2; used.has(fn); n++) fn = `${camel(pascal(r.tag))}${n}`;
    used.add(fn);
    r.fn = fn;
    const failure = chosen.get(r.tag) ?? r.failure ?? "NeverFailure";
    o.push(
      `  public static let ${ident(fn)} = RpcSpec<${wireType(r.payload)}, ${wireType(r.success)}, ${failure}>(tag: ${swiftString(r.tag)}, isStream: ${r.isStream})`,
    );
  }
  o.push("");
  o.push("  /// Every wire tag in `WsRpcGroup`, in declaration order.");
  o.push("  public static let allTags: [String] = [");
  for (const r of rpcs) o.push(`    ${swiftString(r.tag)},`);
  o.push("  ]");
  o.push("}");
  return o.join("\n") + "\n";
}

export function emitHttp(https: HttpModel[], taken: Set<string>): string {
  const o: string[] = [HEADER];
  const keyOf = (h: HttpModel) => `${h.group}.${h.name}`;
  const { lines, chosen } = failureAliases(
    https.map((h) => ({
      key: keyOf(h),
      alias: `Http${pascal(h.group)}${pascal(h.name)}Failure`,
      failure: h.failure,
    })),
    taken,
  );
  o.push(...lines, "");
  o.push("/// Endpoints of `EnvironmentHttpApi` (packages/contracts/src/environmentHttp.ts).");
  o.push(
    "/// `params` are `:name` path segments, `query` is the URL query string, `body` is the request body.",
  );
  o.push("public enum Http {");
  for (const h of https) {
    const fn = camel(`${h.group} ${h.name}`);
    const failure = chosen.get(keyOf(h)) ?? h.failure ?? "NeverFailure";
    const ty = (w: Wire | null) => (w ? wireType(w) : "EmptyObject");
    const statuses = Object.keys(h.errorStatuses)
      .sort()
      .map((k) => `${swiftString(k)}: ${h.errorStatuses[k]}`);
    o.push(
      `  public static let ${ident(fn)} = HttpSpec<${ty(h.params)}, ${ty(h.query)}, ${ty(h.payload)}, ${wireType(h.success)}, ${failure}>(`,
    );
    o.push(
      `    group: ${swiftString(h.group)}, name: ${swiftString(h.name)}, method: ${swiftString(h.method)}, path: ${swiftString(h.path)},`,
    );
    o.push(
      `    bodyContentType: ${h.payloadContentType ? swiftString(h.payloadContentType) : "nil"},`,
    );
    o.push(`    errorStatuses: [${statuses.length ? statuses.join(", ") : ":"}]`);
    o.push("  )");
  }
  o.push("}");
  return o.join("\n") + "\n";
}
